CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, full_name text NOT NULL DEFAULT '' CHECK(char_length(full_name)<=100), username text UNIQUE CHECK(username ~ '^[a-z0-9_]{3,24}$'), country text NOT NULL DEFAULT '' CHECK(char_length(country)<=80), locality text NOT NULL DEFAULT '' CHECK(char_length(locality)<=100));
GRANT SELECT ON public.profiles TO authenticated; GRANT UPDATE(full_name,username,country,locality) ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_profile_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid());
CREATE POLICY own_profile_update ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE FUNCTION public.create_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,full_name,username,country,locality) VALUES(NEW.id,coalesce(NEW.raw_user_meta_data->>'full_name',''),nullif(lower(NEW.raw_user_meta_data->>'username'),''),coalesce(NEW.raw_user_meta_data->>'country',''),coalesce(NEW.raw_user_meta_data->>'locality','')); RETURN NEW; END; $$;
CREATE TRIGGER account_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_profile();
CREATE TABLE public.friendships (requester uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, recipient uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted')), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(requester,recipient), CHECK(requester<>recipient));
GRANT SELECT,DELETE ON public.friendships TO authenticated; GRANT ALL ON public.friendships TO service_role;
ALTER TABLE public.friendships ENABLE ROW LEVEL SECURITY;
CREATE POLICY friend_read ON public.friendships FOR SELECT TO authenticated USING(auth.uid() IN (requester,recipient));
CREATE POLICY friend_remove ON public.friendships FOR DELETE TO authenticated USING(auth.uid() IN (requester,recipient));
CREATE TABLE public.video_submissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, video_hash text NOT NULL UNIQUE, storage_path text NOT NULL, correct_items integer NOT NULL DEFAULT 0 CHECK(correct_items>=0 AND correct_items<=100), points integer GENERATED ALWAYS AS (correct_items*10) STORED, result jsonb, status text NOT NULL DEFAULT 'processing' CHECK(status IN ('processing','complete','failed')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.video_submissions TO authenticated; GRANT ALL ON public.video_submissions TO service_role;
ALTER TABLE public.video_submissions ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_videos ON public.video_submissions FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.request_friend(handle text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE target uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; SELECT id INTO target FROM public.profiles WHERE username=lower(trim(handle)); IF target IS NULL THEN RAISE EXCEPTION 'Username not found'; END IF; IF target=auth.uid() THEN RAISE EXCEPTION 'You cannot add yourself'; END IF; IF EXISTS(SELECT 1 FROM public.friendships WHERE requester=target AND recipient=auth.uid()) THEN UPDATE public.friendships SET status='accepted' WHERE requester=target AND recipient=auth.uid(); ELSE INSERT INTO public.friendships(requester,recipient) VALUES(auth.uid(),target) ON CONFLICT DO NOTHING; END IF; END; $$;
CREATE FUNCTION public.accept_friend(sender uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.friendships SET status='accepted' WHERE requester=sender AND recipient=auth.uid(); END; $$;
CREATE FUNCTION public.friend_scores() RETURNS TABLE(id uuid, username text, points bigint, status text, incoming boolean) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.id,p.username,coalesce((SELECT sum(v.points) FROM public.video_submissions v WHERE v.user_id=p.id AND v.status='complete'),0),f.status,f.recipient=auth.uid() FROM public.friendships f JOIN public.profiles p ON p.id=CASE WHEN f.requester=auth.uid() THEN f.recipient ELSE f.requester END WHERE auth.uid() IN (f.requester,f.recipient); $$;
REVOKE ALL ON FUNCTION public.request_friend(text),public.accept_friend(uuid),public.friend_scores() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.request_friend(text),public.accept_friend(uuid),public.friend_scores() TO authenticated;
CREATE POLICY video_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='recycling-videos' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY video_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='recycling-videos' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY video_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='recycling-videos' AND (storage.foldername(name))[1]=auth.uid()::text);